(() => {
  'use strict';
  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
  if (location.hash) history.replaceState(null, '', location.pathname + location.search);
  window.scrollTo(0, 0);

  const $ = (s, r = document) => r.querySelector(s);
  const rack = $('[data-tabs]'), panel = $('[data-panel]');
  const main = $('[data-main]'), blur = $('[data-blur]'), thumbs = $('[data-thumbs]'), count = $('[data-count]');
  const lb = $('[data-lb]'), lbImg = $('[data-lb-img]'), lbN = $('[data-lb-n]');
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  let room = 0, photo = 0, swapTimer = 0;

  ROOMS.forEach((r, i) => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'key'; b.id = 'key-' + r.id;
    b.setAttribute('role', 'tab'); b.setAttribute('aria-controls', 'room-panel');
    b.innerHTML = `<span class="key__tag"><span class="key__no">${r.no}</span><span class="key__cat">${esc(r.cat)}</span></span><span class="key__name">${esc(r.name)}</span>`;
    b.addEventListener('click', () => selectRoom(i, true));
    rack.appendChild(b);
  });

  rack.addEventListener('keydown', e => {
    const map = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
    let n = null;
    if (e.key in map) n = (room + map[e.key] + ROOMS.length) % ROOMS.length;
    if (e.key === 'Home') n = 0;
    if (e.key === 'End') n = ROOMS.length - 1;
    if (n === null) return;
    e.preventDefault(); selectRoom(n, true); rack.children[n].focus({ preventScroll: true });
  });

  function scrollThumb(t) {
    if (!t || thumbs.scrollWidth <= thumbs.clientWidth) return;
    const l = t.offsetLeft - thumbs.offsetLeft;
    if (l < thumbs.scrollLeft || l + t.offsetWidth > thumbs.scrollLeft + thumbs.clientWidth)
      thumbs.scrollTo({ left: Math.max(0, l - 8), behavior: 'smooth' });
  }

  function setPhoto(i, animate = true) {
    const r = ROOMS[room], n = r.photos.length;
    photo = (i + n) % n;
    const src = r.photos[photo], alt = r.alts[photo] || r.name;
    clearTimeout(swapTimer);
    const apply = () => { main.src = src; main.alt = alt; blur.style.backgroundImage = `url("${src}")`; main.classList.remove('is-fading'); };
    if (animate && !matchMedia('(prefers-reduced-motion: reduce)').matches) { main.classList.add('is-fading'); swapTimer = setTimeout(apply, 180); } else apply();
    count.textContent = `${photo + 1} / ${n}`;
    [...thumbs.children].forEach((t, k) => t.setAttribute('aria-current', String(k === photo)));
    scrollThumb(thumbs.children[photo]);
    if (lb.open) { lbImg.src = src; lbImg.alt = alt; lbN.textContent = `${r.name} · ${photo + 1} / ${n}`; }
    const pre = new Image(); pre.src = r.photos[(photo + 1) % n];
  }

  function selectRoom(i, user) {
    room = i; const r = ROOMS[i];
    [...rack.children].forEach((k, j) => { k.setAttribute('aria-selected', String(j === i)); k.tabIndex = j === i ? 0 : -1; });
    panel.setAttribute('aria-labelledby', 'key-' + r.id);
    $('[data-kicker]').textContent = `Ключ № ${r.no} · ${r.cat}`;
    $('[data-name]').textContent = r.name;
    $('[data-text]').textContent = r.text;
    $('[data-spec]').innerHTML = r.spec.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('');
    $('[data-list]').textContent = r.list.join(', ').toLowerCase().replace(/^./, c => c.toUpperCase()).replace(/wi-fi/i, 'Wi-Fi') + '.';
    $('[data-book]').setAttribute('aria-label', `Позвонить и забронировать: ${r.name}`);
    thumbs.innerHTML = r.photos.map((p, k) => `<button type="button" class="thumb" aria-label="Фото ${k + 1}: ${esc(r.alts[k] || r.name)}"><img src="${p}" alt="" loading="lazy" decoding="async"></button>`).join('');
    [...thumbs.children].forEach((t, k) => t.addEventListener('click', () => setPhoto(k)));
    thumbs.scrollLeft = 0;
    setPhoto(0, user);
    if (user) {
      panel.classList.remove('is-swap'); void panel.offsetWidth; panel.classList.add('is-swap');
      const top = panel.getBoundingClientRect().top;
      if (top > innerHeight * .75) panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }

  $('[data-prev]').addEventListener('click', () => setPhoto(photo - 1));
  $('[data-next]').addEventListener('click', () => setPhoto(photo + 1));

  const openLb = () => {
    const r = ROOMS[room];
    lbImg.src = main.src; lbImg.alt = main.alt; lbN.textContent = `${r.name} · ${photo + 1} / ${r.photos.length}`;
    if (typeof lb.showModal === 'function') { lb.showModal(); document.documentElement.style.overflow = 'hidden'; }
    else window.open(main.src, '_blank', 'noopener');
  };
  $('[data-open]').addEventListener('click', openLb);
  lb.addEventListener('close', () => { document.documentElement.style.overflow = ''; });
  $('[data-lb-close]').addEventListener('click', () => lb.close());
  $('[data-lb-prev]').addEventListener('click', () => setPhoto(photo - 1, false));
  $('[data-lb-next]').addEventListener('click', () => setPhoto(photo + 1, false));
  lb.addEventListener('click', e => { if (e.target === lb) lb.close(); });
  document.addEventListener('keydown', e => {
    if (!lb.open) return;
    if (e.key === 'ArrowRight') setPhoto(photo + 1, false);
    if (e.key === 'ArrowLeft') setPhoto(photo - 1, false);
  });

  const swipe = (el, onTap) => {
    let x = 0, y = 0, moved = false;
    el.addEventListener('touchstart', e => { x = e.touches[0].clientX; y = e.touches[0].clientY; moved = false; }, { passive: true });
    el.addEventListener('touchend', e => {
      const dx = e.changedTouches[0].clientX - x, dy = e.changedTouches[0].clientY - y;
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) { moved = true; setPhoto(photo + (dx < 0 ? 1 : -1), el === lb ? false : true); }
    }, { passive: true });
    el.addEventListener('click', e => { if (moved) { e.stopImmediatePropagation(); e.preventDefault(); moved = false; } }, true);
  };
  swipe($('[data-open]')); swipe(lb);

  main.addEventListener('error', () => { main.alt = 'Фото временно недоступно'; });

  selectRoom(0, false);

  const head = $('[data-head]'), dock = $('[data-dock]'), foot = $('#contacts'), keys = $('#keys');
  let footIn = false, pastKeys = false;
  const upd = () => {
    head.classList.toggle('is-stuck', scrollY > 60);
    dock.classList.toggle('is-on', pastKeys && !footIn);
  };
  new IntersectionObserver(([e]) => { footIn = e.isIntersecting; upd(); }).observe(foot);
  new IntersectionObserver(([e]) => { pastKeys = e.isIntersecting || e.boundingClientRect.top < 0; upd(); }).observe(keys);
  addEventListener('scroll', upd, { passive: true }); upd();
})();
